function decorate(html,path,title,desc,id){return html.replace('</head>',schema(path,title,desc)+'</head>').replace('</body>',analytics(id)+'</body>')}

function route(req,res,url){if(!['GET','HEAD'].includes(req.method))return false;const p=url.pathname;let body,type='text/html; charset=utf-8';if(p==='/robots.txt'){type='text/plain; charset=utf-8';body='User-agent: *\nDisallow: /app\nDisallow: /api/\nDisallow: /login\nDisallow: /cadastro\nDisallow: /auth/\nDisallow: /recuperar-senha\nDisallow: /redefinir-senha\nSitemap: '+base+'/sitemap.xml\n';}else if(p==='/sitemap.xml'){type='application/xml; charset=utf-8';body='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+paths.map(x=>'<url><loc>'+base+x+'</loc></url>').join('')+'</urlset>'}else{body=page(p);if(body===null)return false;const item=articles.find(a=>p==='/blog/'+a[0])||tools.find(t=>p==='/ferramentas/'+t[0]);body=decorate(body,p,item?item[1]:p==='/blog'?'Blog Rota 40':'Ferramentas gratuitas',item?(p.startsWith('/blog/')?item[3]:item[2]):'Recursos gratuitos de preparação para a OAB',process.env.GA4_MEASUREMENT_ID)}res.writeHead(200,{'Content-Type':type,'X-Content-Type-Options':'nosniff','Cache-Control':'public, max-age=300'});res.end(req.method==='HEAD'?undefined:body);return true}
module.exports={route,paths,page,decorate,schema,analytics};
